                C("dm08-s2-s5", "Emperor Quazla", new[] { Civilization.Water }, 6, CardType.EvolutionCreature, new[] { "Cyber Lord" }, 5000, "DM-08", "S2/S5", 542, "\u25a0 Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)\n\u25a0 Evolution\u2014Put on one of your Cyber Lords.\n\u25a0 Whenever your opponent uses the \"shield trigger\" ability of one of his shields, draw up to 2 cards.", new[] { new PrintedRuleLine("ability.b050166a20a5", "Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)", "keyword.blocker"), new PrintedRuleLine("ability.d197695cfa9e", "Evolution\u2014Put on one of your Cyber Lords.", "evolution.single_race"), new PrintedRuleLine("ability.b9d3deefa0eb", "Whenever your opponent uses the \"shield trigger\" ability of one of his shields, draw up to 2 cards.", "trigger.opponent_shield_trigger_draw") }),
                C("dm08-s3-s5", "Super Necrodragon Abzo Dolba", new[] { Civilization.Darkness }, 6, CardType.EvolutionCreature, new[] { "Zombie Dragon" }, 11000, "DM-08", "S3/S5", 543, "\u25a0 Evolution\u2014Put on one of your creatures that has Dragon in its race.\n\u25a0 This creature gets +2000 power for each creature in your graveyard.\n\u25a0 Triple breaker (This creature breaks 3 shields.)", new[] { new PrintedRuleLine("ability.d466322476a4", "Evolution\u2014Put on one of your creatures that has Dragon in its race.", "evolution.single_race"), new PrintedRuleLine("ability.62c9edc0602f", "This creature gets +2000 power for each creature in your graveyard.", "static.power_per_graveyard_creature"), new PrintedRuleLine("ability.eab4a0929dfe", "Triple breaker (This creature breaks 3 shields.)", "keyword.triple_breaker") }),
                C("dm08-s4-s5", "Uberdragon Bajula", new[] { Civilization.Fire }, 7, CardType.EvolutionCreature, new[] { "Armored Dragon" }, 13000, "DM-08", "S4/S5", 544, "\u25a0 Evolution\u2014Put on one of your creatures that has Dragon in its race.\n\u25a0 Whenever this creature attacks, choose up to 2 cards in your opponent's mana zone. Your opponent puts those cards into his graveyard.\n\u25a0 Triple breaker (This creature breaks 3 shields.)", new[] { new PrintedRuleLine("ability.d466322476a4", "Evolution\u2014Put on one of your creatures that has Dragon in its race.", "evolution.single_race"), new PrintedRuleLine("ability.361e016c6170", "Whenever this creature attacks, choose up to 2 cards in your opponent's mana zone. Your opponent puts those cards into his graveyard.", "move.attack_opponent_mana_burn"), new PrintedRuleLine("ability.eab4a0929dfe", "Triple breaker (This creature breaks 3 shields.)", "keyword.triple_breaker") }),
                C("dm08-s5-s5", "Super Terradragon Bailas Gale", new[] { Civilization.Nature }, 5, CardType.EvolutionCreature, new[] { "Earth Dragon" }, 9000, "DM-08", "S5/S5", 545, "\u25a0 Evolution\u2014Put on one of your creatures that has Dragon in its race.\n\u25a0 After you cast a spell by using its \"shield trigger\" ability, put it into your hand instead of your graveyard.\n\u25a0 Double breaker (This creature breaks 2 shields.)", new[] { new PrintedRuleLine("ability.d466322476a4", "Evolution\u2014Put on one of your creatures that has Dragon in its race.", "evolution.single_race"), new PrintedRuleLine("ability.d74cbb9729b8", "After you cast a spell by using its \"shield trigger\" ability, put it into your hand instead of your graveyard.", "replacement.shield_trigger_spell_to_hand"), new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker") }),
                C("dm08-1-55", "Kuukai, Finder of Karma", new[] { Civilization.Light }, 5, CardType.EvolutionCreature, new[] { "Mecha Thunder" }, 10500, "DM-08", "1/55", 546, "\u25a0 Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)\n\u25a0 Evolution\u2014Put on one of your Mecha Thunders.\n\u25a0 Whenever this creature blocks, untap it after it battles.\n\u25a0 This creature can't attack players.", new[] { new PrintedRuleLine("ability.b050166a20a5", "Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)", "keyword.blocker"), new PrintedRuleLine("ability.1ca678e873e4", "Evolution\u2014Put on one of your Mecha Thunders.", "evolution.single_race"), new PrintedRuleLine("ability.ee898421daac", "Whenever this creature blocks, untap it after it battles.", "trigger.after_block_battle_untap"), new PrintedRuleLine("ability.e66dc109f1c0", "This creature can't attack players.", "restriction.cannot_attack_players") }),
                C("dm08-2-55", "Aqua Ranger", new[] { Civilization.Water }, 6, CardType.Creature, new[] { "Liquid People" }, 3000, "DM-08", "2/55", 547, "\u25a0 This creature can't be blocked.\n\u25a0 When this creature would be destroyed, put it into your hand instead.", new[] { new PrintedRuleLine("ability.55b08b7c26ea", "This creature can't be blocked.", "restriction.unblockable"), new PrintedRuleLine("ability.5596c4cdd861", "When this creature would be destroyed, put it into your hand instead.", "replacement.destroy_move") }),
                C("dm08-3-55", "Megaria, Empress of Dread", new[] { Civilization.Darkness }, 5, CardType.Creature, new[] { "Dark Lord" }, 5000, "DM-08", "3/55", 548, "\u25a0 Each creature in the battle zone has \"slayer.\" (Whenever a creature that has \"slayer\" battles, destroy the other creature after the battle.)", new[] { new PrintedRuleLine("ability.9db4d37a34e3", "Each creature in the battle zone has \"slayer.\" (Whenever a creature that has \"slayer\" battles, destroy the other creature after the battle.)", "static.global_slayer") }),
                C("dm08-4-55", "Magmadragon Jagalzor", new[] { Civilization.Fire }, 6, CardType.Creature, new[] { "Volcano Dragon" }, 6000, "DM-08", "4/55", 549, "\u25a0 Double breaker (This creature breaks 2 shields.)\n\u25a0 Turbo rush (If any of your other creatures broke any shields this turn, this creature gets its turbo rush ability until the end of the turn.)\n  Each of your creatures in the battle zone has \"speed attacker.\" (A creature that has \"speed attacker\" doesn't get summoning sickness.)", new[] { new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker"), new PrintedRuleLine("ability.3effd704b871", "Turbo rush (If any of your other creatures broke any shields this turn, this creature gets its turbo rush ability until the end of the turn.)", "keyword.turbo_rush"), new PrintedRuleLine("ability.e6fd6b437866", "Each of your creatures in the battle zone has \"speed attacker.\" (A creature that has \"speed attacker\" doesn't get summoning sickness.)", "static.turbo_all_speed_attacker") }),
                C("dm08-5-55", "Kachua, Keeper of the Icegate", new[] { Civilization.Nature }, 7, CardType.Creature, new[] { "Snow Faerie" }, 3000, "DM-08", "5/55", 550, "\u25a0 Instead of having this creature attack, you may tap it to use its tap ability.\n Search your deck. You may take a creature that has Dragon in its race from your deck and put it into the battle zone. Then shuffle your deck. That creature has \"speed attacker.\" At the end of the turn, destroy it.", new[] { new PrintedRuleLine("ability.0a61d1dabe28", "Instead of having this creature attack, you may tap it to use its tap ability.", "keyword.tap_ability"), new PrintedRuleLine("ability.ae2fbcdffcad", "Search your deck. You may take a creature that has Dragon in its race from your deck and put it into the battle zone. Then shuffle your deck. That creature has \"speed attacker.\" At the end of the turn, destroy it.", "compound.tap_summon_temporary_dragon") }),
                C("dm08-6-55", "Dracobarrier", new[] { Civilization.Light }, 3, CardType.Spell, Array.Empty<string>(), 0, "DM-08", "6/55", 551, "\u25a0 Shield trigger (When this card is put into your hand from your shield zone, you may play it immediately for no cost.)\n\u25a0 Choose one of your opponent's creatures in the battle zone and tap it. If it has Dragon in its race, add the top card of your deck to your shields face down.", new[] { new PrintedRuleLine("ability.3491abebb532", "Shield trigger (When this card is put into your hand from your shield zone, you may play it immediately for no cost.)", "keyword.shield_trigger"), new PrintedRuleLine("ability.248525b1bbde", "Choose one of your opponent's creatures in the battle zone and tap it. If it has Dragon in its race, add the top card of your deck to your shields face down.", "compound.tap_then_dragon_shield") }),
                C("dm08-7-55", "Laser Whip", new[] { Civilization.Light }, 4, CardType.Spell, Array.Empty<string>(), 0, "DM-08", "7/55", 552, "\u25a0 Choose one of your opponent's creatures in the battle zone and tap it. Then you may choose one of your creatures in the battle zone. If you do, it can't be blocked this turn.", new[] { new PrintedRuleLine("ability.9abb47efb2e5", "Choose one of your opponent's creatures in the battle zone and tap it. Then you may choose one of your creatures in the battle zone. If you do, it can't be blocked this turn.", "compound.tap_then_unblockable") }),
                C("dm08-8-55", "Lunar Charger", new[] { Civilization.Light }, 3, CardType.Spell, Array.Empty<string>(), 0, "DM-08", "8/55", 553, "\u25a0 Choose up to 2 of your creatures in the battle zone. At the end of the turn, you may untap them.\n\u25a0 Charger (After you cast this spell, put it into your mana zone instead of your graveyard.)", new[] { new PrintedRuleLine("ability.c4f59c1c79f6", "Choose up to 2 of your creatures in the battle zone. At the end of the turn, you may untap them.", "delayed.chosen_untap_end_turn"), new PrintedRuleLine("ability.27d6da0e8540", "Charger (After you cast this spell, put it into your mana zone instead of your graveyard.)", "keyword.charger") }),
                C("dm08-9-55", "Migalo, Vizier of Spycraft", new[] { Civilization.Light }, 2, CardType.Creature, new[] { "Initiate" }, 1500, "DM-08", "9/55", 554, "\u25a0 Turbo rush (If any of your other creatures broke any shields this turn, this creature gets its turbo rush ability until the end of the turn.)\n  Whenever this creature attacks, you may look at 2 of your opponent's shields. Then put them back where they were.", new[] { new PrintedRuleLine("ability.3effd704b871", "Turbo rush (If any of your other creatures broke any shields this turn, this creature gets its turbo rush ability until the end of the turn.)", "keyword.turbo_rush"), new PrintedRuleLine("ability.afa8dfbffb77", "Whenever this creature attacks, you may look at 2 of your opponent's shields. Then put them back where they were.", "look.attack_opponent_shields") }),
