                C("dm08-12-55", "Sasha, Channeler of Suns", new[] { Civilization.Light }, 8, CardType.Creature, new[] { "Mecha Del Sol" }, 9500, "DM-08", "12/55", 557, "\u25a0 Dragon blocker (Whenever an opponent's creature that has Dragon in its race attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)\n\u25a0 While battling a creature that has Dragon in its race, this creature gets +6000 power.\n\u25a0 Double breaker (This creature breaks 2 shields.)", new[] { new PrintedRuleLine("ability.f5d6c7d32792", "Dragon blocker (Whenever an opponent's creature that has Dragon in its race attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)", "keyword.dragon_blocker"), new PrintedRuleLine("ability.9b731423629f", "While battling a creature that has Dragon in its race, this creature gets +6000 power.", "static.battle_dragon_power"), new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker") }),
