                C("dm09-53-55", "Vine Charger", new[] { Civilization.Nature }, 4, CardType.Spell, Array.Empty<string>(), 0, "DM-09", "53/55", 658, "\u25a0 Your opponent chooses one of his creatures in the battle zone and puts it into his mana zone.\n\u25a0 Charger (After you cast this spell, put it into your mana zone instead of your graveyard.)", new[] { new PrintedRuleLine("ability.ba4631c33561", "Your opponent chooses one of his creatures in the battle zone and puts it into his mana zone.", "move.opponent_choice_creature_to_mana"), new PrintedRuleLine("ability.27d6da0e8540", "Charger (After you cast this spell, put it into your mana zone instead of your graveyard.)", "keyword.charger") }),
                C("dm09-54-55", "Whip Scorpion", new[] { Civilization.Nature }, 5, CardType.Creature, new[] { "Giant Insect" }, 2000, "DM-09", "54/55", 659, "\u25a0 Shield trigger (When this card is put into your hand from your shield zone, you may play it immediately for no cost.)\n\u25a0 Power attacker +3000 (While attacking, this creature gets +3000 power.)", new[] { new PrintedRuleLine("ability.3491abebb532", "Shield trigger (When this card is put into your hand from your shield zone, you may play it immediately for no cost.)", "keyword.shield_trigger"), new PrintedRuleLine("ability.9df93a091ec8", "Power attacker +3000 (While attacking, this creature gets +3000 power.)", "keyword.power_attacker") }),
                C("dm09-55-55", "Whispering Totem", new[] { Civilization.Nature }, 4, CardType.Creature, new[] { "Mystery Totem" }, 2000, "DM-09", "55/55", 660, "\u25a0 When you put this creature into the battle zone, search your deck. You may take a Whispering Totem from your deck, show that creature to your opponent, and put it into your hand. Then shuffle your deck.", new[] { new PrintedRuleLine("ability.f00ce055161c", "When you put this creature into the battle zone, search your deck. You may take a Whispering Totem from your deck, show that creature to your opponent, and put it into your hand. Then shuffle your deck.", "search.summon_whispering_totem") }),
                C("dm10-s1-s10", "Elixia, Pureblade Elemental", new[] { Civilization.Light }, 6, CardType.Creature, new[] { "Angel Command" }, 1000, "DM-10", "S1/S10", 661, "\u25a0 This creature gets +3000 power for each civilization in your mana zone.\n\u25a0 While this creature has power 6000 or more, it has \"double breaker (This creature break 2 shields).\"\n\u25a0 While this creature has power 15000 or more, it has \"triple breaker\" instead of \"double breaker.\" (It breaks 3 shields.)", new[] { new PrintedRuleLine("ability.04e6af16f7a6", "This creature gets +3000 power for each civilization in your mana zone.", "runtime.dm10.04e6af16f7a6"), new PrintedRuleLine("ability.e30bd12ae7ab", "While this creature has power 6000 or more, it has \"double breaker (This creature break 2 shields).\"", "static.power_threshold_double_breaker"), new PrintedRuleLine("ability.8a6972fab8fd", "While this creature has power 15000 or more, it has \"triple breaker\" instead of \"double breaker.\" (It breaks 3 shields.)", "static.power_threshold_triple_breaker") }),
                C("dm10-s2-s10", "Hawkeye Lunatron", new[] { Civilization.Water }, 8, CardType.Creature, new[] { "Cyber Moon" }, 6000, "DM-10", "S2/S10", 662, "\u25a0 Double breaker (This creature breaks 2 shields.)\n\u25a0 When you put this creature into the battle zone, search your deck. You may take a card from your deck and put it into your hand. Then shuffle your deck.", new[] { new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker"), new PrintedRuleLine("ability.bc8d24b3f0b8", "When you put this creature into the battle zone, search your deck. You may take a card from your deck and put it into your hand. Then shuffle your deck.", "search.deck_filtered") }),
                C("dm10-s3-s10", "Hurricane Crawler", new[] { Civilization.Water }, 5, CardType.Creature, new[] { "Earth Eater" }, 4000, "DM-10", "S3/S10", 663, "\u25a0 When you put this creature into the battle zone, put all the cards from your hand into your mana zone. Then put that many cards from your mana zone into your hand.", new[] { new PrintedRuleLine("ability.50f1a753a7c4", "When you put this creature into the battle zone, put all the cards from your hand into your mana zone. Then put that many cards from your mana zone into your hand.", "runtime.dm10.50f1a753a7c4") }),
                C("dm10-s4-s10", "Necrodragon Bryzenaga", new[] { Civilization.Darkness }, 6, CardType.Creature, new[] { "Zombie Dragon" }, 9000, "DM-10", "S4/S10", 664, "\u25a0 When you put this creature into the battle zone, put all your shields into your hand. (You can use the \"shield trigger\" abilities of those shields.)\n\u25a0 Double breaker (This creature breaks 2 shields.)", new[] { new PrintedRuleLine("ability.3fc6344e245e", "When you put this creature into the battle zone, put all your shields into your hand. (You can use the \"shield trigger\" abilities of those shields.)", "runtime.dm10.529570c56c3b"), new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker") }),
                C("dm10-s5-s10", "Core-Crash Lizard", new[] { Civilization.Fire }, 7, CardType.Creature, new[] { "Melt Warrior" }, 6000, "DM-10", "S5/S10", 665, "\u25a0 When you put this creature into the battle zone, choose one of your opponent's shields and put it into his graveyard.", new[] { new PrintedRuleLine("ability.9a02dde1dd79", "When you put this creature into the battle zone, choose one of your opponent's shields and put it into his graveyard.", "runtime.dm10.9a02dde1dd79") }),
                C("dm10-s6-s10", "Ultimate Dragon", new[] { Civilization.Fire }, 6, CardType.Creature, new[] { "Armored Dragon" }, 5000, "DM-10", "S6/S10", 666, "\u25a0 This creature gets +5000 power for each of your other creatures in the battle zone that has Dragon in its race.\n\u25a0 Crew breaker\u2014Dragon (This creature breaks one more shield for each of your other creatures in the battle zone that has Dragon in its race.)", new[] { new PrintedRuleLine("ability.2d5e0982b1e8", "This creature gets +5000 power for each of your other creatures in the battle zone that has Dragon in its race.", "runtime.dm10.2d5e0982b1e8"), new PrintedRuleLine("ability.ae7827378dca", "Crew breaker\u2014Dragon (This creature breaks one more shield for each of your other creatures in the battle zone that has Dragon in its race.)", "keyword.crew_breaker") }),
                C("dm10-s7-s10", "Bodacious Giant", new[] { Civilization.Nature }, 8, CardType.Creature, new[] { "Giant" }, 12000, "DM-10", "S7/S10", 667, "\u25a0 Double breaker (This creature breaks 2 shields.)\n\u25a0 While this creature is tapped during your opponent's turn, if it hasn't been attacked that turn, your opponent's creatures must attack it if able.", new[] { new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker"), new PrintedRuleLine("ability.fea38b9f44e1", "While this creature is tapped during your opponent's turn, if it hasn't been attacked that turn, your opponent's creatures must attack it if able.", "runtime.dm10.fea38b9f44e1") }),
