                C("dm10-s9-s10", "Bluum Erkis, Flare Guardian", new[] { Civilization.Light, Civilization.Water }, 6, CardType.Creature, new[] { "Guardian" }, 8500, "DM-10", "S9/S10", 669, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Whenever this creature would break one of your opponent's shields, your opponent shows that shield to you instead of putting it into his hand. If it's a spell that has \"shield trigger,\" you cast it for no cost, then put it into your opponent's graveyard. If it's not, your opponent puts it into his hand.\n\u25a0 Double breaker", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.d529fbf574b3", "Whenever this creature would break one of your opponent's shields, your opponent shows that shield to you instead of putting it into his hand. If it's a spell that has \"shield trigger,\" you cast it for no cost, then put it into your opponent's graveyard. If it's not, your opponent puts it into his hand.", "runtime.dm10.3dc5b0462871"), new PrintedRuleLine("ability.a0d5f70083eb", "Double breaker", "keyword.double_breaker") }),
                C("dm10-s10-s10", "Deklowaz, the Terminator", new[] { Civilization.Darkness, Civilization.Fire }, 6, CardType.Creature, new[] { "Spirit Quartz" }, 5000, "DM-10", "S10/S10", 670, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Instead of having this creature attack, you may tap it to use its tap ability.\n Destroy all creatures that have power 3000 or less. Then look at your opponent's hand. He discards all creatures from it that have power 3000 or less.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.0a61d1dabe28", "Instead of having this creature attack, you may tap it to use its tap ability.", "keyword.tap_ability"), new PrintedRuleLine("ability.68b39aa4f140", "Destroy all creatures that have power 3000 or less. Then look at your opponent's hand. He discards all creatures from it that have power 3000 or less.", "runtime.dm10.c5d0bb07f5b8") }),
                C("dm10-1-110", "Balza, Seeker of Hyperpearls", new[] { Civilization.Light }, 8, CardType.Creature, new[] { "Mecha Thunder" }, 4000, "DM-10", "1/110", 671, "\u25a0 Shield trigger (When this card is put into your hand from your shield zone, you may play it immediately for no cost.)\n\u25a0 Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)\n\u25a0 This creature can't attack players.", new[] { new PrintedRuleLine("ability.3491abebb532", "Shield trigger (When this card is put into your hand from your shield zone, you may play it immediately for no cost.)", "keyword.shield_trigger"), new PrintedRuleLine("ability.b050166a20a5", "Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)", "keyword.blocker"), new PrintedRuleLine("ability.e66dc109f1c0", "This creature can't attack players.", "restriction.cannot_attack_players") }),
