                C("dm10-99-110", "Melnia, the Aqua Shadow", new[] { Civilization.Water, Civilization.Darkness }, 2, CardType.Creature, new[] { "Liquid People", "Ghost" }, 1000, "DM-10", "99/110", 769, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 This creature can't be blocked.\n\u25a0 Slayer (Whenever this creature battles, destroy the other creature after the battle.)", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.55b08b7c26ea", "This creature can't be blocked.", "restriction.unblockable"), new PrintedRuleLine("ability.6efd7c234e5b", "Slayer (Whenever this creature battles, destroy the other creature after the battle.)", "keyword.slayer") }),
