                C("dm10-101-110", "Soderlight, the Cold Blade", new[] { Civilization.Water, Civilization.Darkness }, 4, CardType.Creature, new[] { "Spirit Quartz" }, 4000, "DM-10", "101/110", 771, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 This creature can't be blocked.\n\u25a0 Silent skill (At the start of each of your turns, if this creature is tapped, you may keep it tapped and use its silent skill ability.)\n  Your opponent chooses one of his creatures and destroys it.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.55b08b7c26ea", "This creature can't be blocked.", "restriction.unblockable"), new PrintedRuleLine("ability.01de49a5d579", "Silent skill (At the start of each of your turns, if this creature is tapped, you may keep it tapped and use its silent skill ability.)", "keyword.silent_skill"), new PrintedRuleLine("ability.e0703a917185", "Your opponent chooses one of his creatures and destroys it.", "runtime.dm10.e0703a917185") }),
                C("dm10-102-110", "Dolmarks, the Shadow Warrior", new[] { Civilization.Darkness, Civilization.Fire }, 4, CardType.Creature, new[] { "Ghost", "Human" }, 4000, "DM-10", "102/110", 772, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 When you put this creature into the battle zone, destroy one of your creatures and put a card from your mana zone into your graveyard. Then your opponent chooses and destroys one of his creatures and chooses a card in his mana zone and puts it into his graveyard.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.c79b88077a78", "When you put this creature into the battle zone, destroy one of your creatures and put a card from your mana zone into your graveyard. Then your opponent chooses and destroys one of his creatures and chooses a card in his mana zone and puts it into his graveyard.", "runtime.dm10.a02724bc6e05") }),
                C("dm10-103-110", "Galek, the Shadow Warrior", new[] { Civilization.Darkness, Civilization.Fire }, 5, CardType.Creature, new[] { "Ghost", "Human" }, 2000, "DM-10", "103/110", 773, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 When you put this creature into the battle zone, destroy one of your opponent's creatures that has \"blocker.\" Then your opponent discards a card at random from his hand.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.cb04aad138bb", "When you put this creature into the battle zone, destroy one of your opponent's creatures that has \"blocker.\" Then your opponent discards a card at random from his hand.", "runtime.dm10.039e37e93d40") }),
                C("dm10-104-110", "Ulex, the Dauntless", new[] { Civilization.Darkness, Civilization.Fire }, 3, CardType.Creature, new[] { "Spirit Quartz" }, 3000, "DM-10", "104/110", 774, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Your opponent can't tap this creature.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.2efcf66a91d3", "Your opponent can't tap this creature.", "runtime.dm10.2efcf66a91d3") }),
                C("dm10-105-110", "Gonta, the Warrior Savage", new[] { Civilization.Fire, Civilization.Nature }, 2, CardType.Creature, new[] { "Human", "Beast Folk" }, 4000, "DM-10", "105/110", 775, "\u25a0 (This creature is put into your mana zone tapped.)", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped") }),
                C("dm10-106-110", "Tagtapp, the Retaliator", new[] { Civilization.Fire, Civilization.Nature }, 3, CardType.Creature, new[] { "Spirit Quartz" }, 3000, "DM-10", "106/110", 776, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 This creature gets +1000 power for each water card in your opponent's mana zone.\n\u25a0 While this creature has power 6000 or more, it has \"Double breaker (This creature breaks 2 shields).\"", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.ec5e064f5916", "This creature gets +1000 power for each water card in your opponent's mana zone.", "runtime.dm10.ec5e064f5916"), new PrintedRuleLine("ability.d6a6a1225478", "While this creature has power 6000 or more, it has \"Double breaker (This creature breaks 2 shields).\"", "static.power_threshold_double_breaker") }),
                C("dm10-107-110", "Wind Axe, the Warrior Savage", new[] { Civilization.Fire, Civilization.Nature }, 5, CardType.Creature, new[] { "Human", "Beast Folk" }, 2000, "DM-10", "107/110", 777, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 When you put this creature into the battle zone, destroy one of your opponent's creatures that has \"blocker.\" Then put the top card of your deck into your mana zone.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.f942b3e4c066", "When you put this creature into the battle zone, destroy one of your opponent's creatures that has \"blocker.\" Then put the top card of your deck into your mana zone.", "runtime.dm10.f942b3e4c066") }),
                C("dm10-108-110", "Lukia Lex, Pinnacle Guardian", new[] { Civilization.Light, Civilization.Nature }, 3, CardType.Creature, new[] { "Guardian" }, 2500, "DM-10", "108/110", 778, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Power attacker +3000 (While attacking, this creature gets +3000 power.)\n\u25a0 At the end of each of your turns, you may untap this creature.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.9df93a091ec8", "Power attacker +3000 (While attacking, this creature gets +3000 power.)", "keyword.power_attacker"), new PrintedRuleLine("ability.59648fa653aa", "At the end of each of your turns, you may untap this creature.", "trigger.end_turn_untap_self") }),
                C("dm10-109-110", "Sanfist, the Savage Vizier", new[] { Civilization.Light, Civilization.Nature }, 3, CardType.Creature, new[] { "Beast Folk", "Initiate" }, 3000, "DM-10", "109/110", 779, "\u25a0 Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)\n\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 When this creature would be discarded from your hand during your opponent's turn, you may put it into the battle zone instead.", new[] { new PrintedRuleLine("ability.b050166a20a5", "Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)", "keyword.blocker"), new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.bbf1ce2377fa", "When this creature would be discarded from your hand during your opponent's turn, you may put it into the battle zone instead.", "runtime.dm10.bbf1ce2377fa") }),
                C("dm10-110-110", "Skysword, the Savage Vizier", new[] { Civilization.Light, Civilization.Nature }, 5, CardType.Creature, new[] { "Beast Folk", "Initiate" }, 2000, "DM-10", "110/110", 780, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 When you put this creature into the battle zone, put the top card of your deck into your mana zone. Then add the top card of your deck to your shields face down.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.f5c5cc68e341", "When you put this creature into the battle zone, put the top card of your deck into your mana zone. Then add the top card of your deck to your shields face down.", "runtime.dm10.f5c5cc68e341") }),
                C("dm11-s1-s5", "Warlord Ailzonius", new[] { Civilization.Light }, 5, CardType.EvolutionCreature, new[] { "Gladiator" }, 8000, "DM-11", "S1/S5", 781, "\u25a0 Evolution\u2014Put on one of your Gladiators.\n\u25a0 Double breaker (This creature breaks 2 shields.)\n\u25a0 Whenever your opponent would choose a creature in the battle zone, he can't choose this one. (It can still be attacked and blocked.)", new[] { new PrintedRuleLine("ability.f903d2d9c286", "Evolution\u2014Put on one of your Gladiators.", "evolution.single_race"), new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker"), new PrintedRuleLine("ability.c227c764e85a", "Whenever your opponent would choose a creature in the battle zone, he can't choose this one. (It can still be attacked and blocked.)", "restriction.opponent_cannot_choose") }),
                C("dm11-s2-s5", "Klujadras", new[] { Civilization.Water }, 7, CardType.Creature, new[] { "Sea Hacker" }, 4000, "DM-11", "S2/S5", 782, "\u25a0 Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)\n  When you put this creature into the battle zone, each player draws a card for each of his creatures in the battle zone that has \"wave striker.\"\n", new[] { new PrintedRuleLine("ability.faa81fc27085", "Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)", "keyword.wave_striker"), new PrintedRuleLine("ability.8a661584ba3a", "When you put this creature into the battle zone, each player draws a card for each of his creatures in the battle zone that has \"wave striker.\"", "runtime.dm11.8a661584ba3a") }),
                C("dm11-s3-s5", "Miraculous Plague", new[] { Civilization.Water, Civilization.Darkness }, 7, CardType.Spell, Array.Empty<string>(), 0, "DM-11", "S3/S5", 783, "\u25a0 (This spell is put into your mana zone tapped.)\n\u25a0 Choose 2 of your opponent's creatures in the battle zone. Your opponent chooses one of them, puts it into his hand, and destroys the other one. Then choose 2 cards in your opponent's mana zone. Your opponent chooses one of them, puts it into his hand, and puts the other one into his graveyard.", new[] { new PrintedRuleLine("ability.7366edaa48d6", "(This spell is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.17fc8cb6d25e", "Choose 2 of your opponent's creatures in the battle zone. Your opponent chooses one of them, puts it into his hand, and destroys the other one. Then choose 2 cards in your opponent's mana zone. Your opponent chooses one of them, puts it into his hand, and puts the other one into his graveyard.", "runtime.dm11.f04bb9176d7a") }),
                C("dm11-s4-s5", "Miraculous Meltdown", new[] { Civilization.Darkness, Civilization.Fire }, 6, CardType.Spell, Array.Empty<string>(), 0, "DM-11", "S4/S5", 784, "\u25a0 (This spell is put into your mana zone tapped.)\n\u25a0 You can cast this spell only if your opponent has more shields than you do.\n\u25a0 Your opponent chooses one of his shields for each shield you have. He puts the rest of his shields into his hand. (He can use the \"shield trigger\" abilities of those shields.)", new[] { new PrintedRuleLine("ability.7366edaa48d6", "(This spell is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.297c6ca8772b", "You can cast this spell only if your opponent has more shields than you do.", "runtime.dm11.297c6ca8772b"), new PrintedRuleLine("ability.ef361a421d0b", "Your opponent chooses one of his shields for each shield you have. He puts the rest of his shields into his hand. (He can use the \"shield trigger\" abilities of those shields.)", "runtime.dm11.abffb6172ddd") }),
                C("dm11-s5-s5", "Miraculous Rebirth", new[] { Civilization.Fire, Civilization.Nature }, 6, CardType.Spell, Array.Empty<string>(), 0, "DM-11", "S5/S5", 785, "\u25a0 (This spell is put into your mana zone tapped.)\n\u25a0 Destroy one of your opponent's creatures that has power 5000 or less. When your opponent puts that creature into his graveyard, search your deck. You may take a creature from your deck that has the same cost as that creature and put it into the battle zone. Then shuffle your deck.", new[] { new PrintedRuleLine("ability.7366edaa48d6", "(This spell is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.0f7f72491a7c", "Destroy one of your opponent's creatures that has power 5000 or less. When your opponent puts that creature into his graveyard, search your deck. You may take a creature from your deck that has the same cost as that creature and put it into the battle zone. Then shuffle your deck.", "runtime.dm11.2564bae63bbc") }),
                C("dm11-1-55", "Evil Incarnate", new[] { Civilization.Darkness }, 6, CardType.EvolutionCreature, new[] { "Devil Mask" }, 11000, "DM-11", "1/55", 786, "\u25a0 Evolution\u2014Put on one of your Devil Masks.\n\u25a0 At the start of each player's turn, that player chooses one of his creatures and destroys it.\n\u25a0 Double breaker (This creature breaks 2 shields.)", new[] { new PrintedRuleLine("ability.cd84a282d698", "Evolution\u2014Put on one of your Devil Masks.", "evolution.single_race"), new PrintedRuleLine("ability.6cf4753f11ad", "At the start of each player's turn, that player chooses one of his creatures and destroys it.", "runtime.dm11.6cf4753f11ad"), new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker") }),
                C("dm11-2-55", "Heavyweight Dragon", new[] { Civilization.Fire }, 7, CardType.Creature, new[] { "Armored Dragon" }, 9000, "DM-11", "2/55", 787, "\u25a0 Double breaker (This creature breaks 2 shields.)\n\u25a0 Instead of having this creature attack, you may tap it to use its tap ability.\n Choose up to 2 of your opponent's tapped creatures in the battle zone. If they have total power less than this creature's power, destroy them.", new[] { new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker"), new PrintedRuleLine("ability.0a61d1dabe28", "Instead of having this creature attack, you may tap it to use its tap ability.", "keyword.tap_ability"), new PrintedRuleLine("ability.059040a66e08", "Choose up to 2 of your opponent's tapped creatures in the battle zone. If they have total power less than this creature's power, destroy them.", "runtime.dm11.059040a66e08") }),
                C("dm11-3-55", "Diamondia, the Blizzard Rider", new[] { Civilization.Nature }, 3, CardType.EvolutionCreature, new[] { "Snow Faerie" }, 5000, "DM-11", "3/55", 788, "\u25a0 Evolution\u2014Put on one of your Snow Faeries.\n\u25a0 When you put this creature into the battle zone, return all Snow Faeries from your graveyard and your mana zone to your hand.", new[] { new PrintedRuleLine("ability.6b9714158350", "Evolution\u2014Put on one of your Snow Faeries.", "evolution.single_race"), new PrintedRuleLine("ability.7458e2c1e600", "When you put this creature into the battle zone, return all Snow Faeries from your graveyard and your mana zone to your hand.", "runtime.dm11.7458e2c1e600") }),
                C("dm11-4-55", "Miraculous Snare", new[] { Civilization.Light, Civilization.Water }, 3, CardType.Spell, Array.Empty<string>(), 0, "DM-11", "4/55", 789, "\u25a0 (This spell is put into your mana zone tapped.)\n\u25a0 Choose a non-evolution creature in the battle zone and add it to its owner's shields face down.", new[] { new PrintedRuleLine("ability.7366edaa48d6", "(This spell is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.138f9e770072", "Choose a non-evolution creature in the battle zone and add it to its owner's shields face down.", "runtime.dm11.138f9e770072") }),
                C("dm11-5-55", "Miraculous Truce", new[] { Civilization.Light, Civilization.Nature }, 5, CardType.Spell, Array.Empty<string>(), 0, "DM-11", "5/55", 790, "\u25a0 Shield trigger (When this card is put into your hand from your shield zone, you may play it immediately for no cost.)\n\u25a0 (This spell is put into your mana zone tapped.)\n\u25a0 Choose a civilization. Until the start of your next turn, creatures of that civilization can't attack you even if your opponent puts them into the battle zone after you cast this spell.", new[] { new PrintedRuleLine("ability.3491abebb532", "Shield trigger (When this card is put into your hand from your shield zone, you may play it immediately for no cost.)", "keyword.shield_trigger"), new PrintedRuleLine("ability.7366edaa48d6", "(This spell is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.4a23b029e0ce", "Choose a civilization. Until the start of your next turn, creatures of that civilization can't attack you even if your opponent puts them into the battle zone after you cast this spell.", "runtime.dm11.0e953b9be1b8") }),
                C("dm11-6-55", "Asra, Vizier of Safety", new[] { Civilization.Light }, 3, CardType.Creature, new[] { "Initiate" }, 2000, "DM-11", "6/55", 791, "\u25a0 Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)\n  This creature gets +4000 power and has \"blocker\". (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)", new[] { new PrintedRuleLine("ability.faa81fc27085", "Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)", "keyword.wave_striker"), new PrintedRuleLine("ability.fb0302b33b67", "This creature gets +4000 power and has \"blocker\". (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)", "runtime.dm11.e09671157cf0") }),
                C("dm11-7-55", "Baraid, the Explorer", new[] { Civilization.Light }, 5, CardType.Creature, new[] { "Gladiator" }, 5000, "DM-11", "7/55", 792, "\u25a0 Silent skill (At the start of each of your turns, if this creature is tapped, you may keep it tapped and use its silent skill ability.)\n  Your light creatures can't be blocked this turn.", new[] { new PrintedRuleLine("ability.01de49a5d579", "Silent skill (At the start of each of your turns, if this creature is tapped, you may keep it tapped and use its silent skill ability.)", "keyword.silent_skill"), new PrintedRuleLine("ability.ed4b4a629524", "Your light creatures can't be blocked this turn.", "runtime.dm11.ed4b4a629524") }),
                C("dm11-8-55", "Belix, the Explorer", new[] { Civilization.Light }, 2, CardType.Creature, new[] { "Gladiator" }, 3000, "DM-11", "8/55", 793, "\u25a0 Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)\n\u25a0 When you put this creature into the battle zone, return a spell from your mana zone to your hand.\n\u25a0 This creature can't attack players.", new[] { new PrintedRuleLine("ability.b050166a20a5", "Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)", "keyword.blocker"), new PrintedRuleLine("ability.668a365e60a2", "When you put this creature into the battle zone, return a spell from your mana zone to your hand.", "move.selected"), new PrintedRuleLine("ability.e66dc109f1c0", "This creature can't attack players.", "restriction.cannot_attack_players") }),
                C("dm11-9-55", "Engbelt, the Spydroid", new[] { Civilization.Light }, 4, CardType.Creature, new[] { "Soltrooper" }, 5500, "DM-11", "9/55", 794, "\u25a0 Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)\n\u25a0 This creature can't attack players.", new[] { new PrintedRuleLine("ability.b050166a20a5", "Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)", "keyword.blocker"), new PrintedRuleLine("ability.e66dc109f1c0", "This creature can't attack players.", "restriction.cannot_attack_players") }),
                C("dm11-10-55", "Lamiel, Destiny Enforcer", new[] { Civilization.Light }, 5, CardType.Creature, new[] { "Berserker" }, 3000, "DM-11", "10/55", 795, "\u25a0 Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)\n  Whenever one of your creatures is destroyed during your opponent's turn, you may draw a card.\n", new[] { new PrintedRuleLine("ability.faa81fc27085", "Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)", "keyword.wave_striker"), new PrintedRuleLine("ability.d4974736115c", "Whenever one of your creatures is destroyed during your opponent's turn, you may draw a card.", "runtime.dm11.d4974736115c") }),
                C("dm11-11-55", "Merlee, the Oracle", new[] { Civilization.Light }, 2, CardType.Creature, new[] { "Light Bringer" }, 1500, "DM-11", "11/55", 796, "\u25a0 Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)\n  Each of your creatures in the battle zone gets +1000 power.\n", new[] { new PrintedRuleLine("ability.faa81fc27085", "Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)", "keyword.wave_striker"), new PrintedRuleLine("ability.9ac4acef9c66", "Each of your creatures in the battle zone gets +1000 power.", "runtime.dm11.9ac4acef9c66") }),
