                C("dm11-50-55", "Skyscraper Shell", new[] { Civilization.Nature }, 4, CardType.Creature, new[] { "Colony Beetle" }, 2000, "DM-11", "50/55", 835, "\u25a0 Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)\n  When you put this creature into the battle zone, your opponent chooses one of his creatures in the battle zone and puts it into his mana zone.\n", new[] { new PrintedRuleLine("ability.faa81fc27085", "Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)", "keyword.wave_striker"), new PrintedRuleLine("ability.946be6ea971f", "When you put this creature into the battle zone, your opponent chooses one of his creatures in the battle zone and puts it into his mana zone.", "move.opponent_choice_creature_to_mana") }),
                C("dm11-51-55", "Rise and Shine", new[] { Civilization.Light, Civilization.Water }, 4, CardType.Spell, Array.Empty<string>(), 0, "DM-11", "51/55", 836, "\u25a0 Shield trigger (When this card is put into your hand from your shield zone, you may play it immediately for no cost.)\n\u25a0 (This spell is put into your mana zone tapped.)\n\u25a0 Reveal the top 4 cards of your deck. Put one of them that has \"blocker\" into your hand, and put the rest on the bottom of your deck in any order.", new[] { new PrintedRuleLine("ability.3491abebb532", "Shield trigger (When this card is put into your hand from your shield zone, you may play it immediately for no cost.)", "keyword.shield_trigger"), new PrintedRuleLine("ability.7366edaa48d6", "(This spell is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.71fb8d85fc81", "Reveal the top 4 cards of your deck. Put one of them that has \"blocker\" into your hand, and put the rest on the bottom of your deck in any order.", "runtime.dm11.f785bc609066") }),
                C("dm11-52-55", "Live and Breathe", new[] { Civilization.Light, Civilization.Nature }, 3, CardType.Spell, Array.Empty<string>(), 0, "DM-11", "52/55", 837, "\u25a0 (This spell is put into your mana zone tapped.)\n\u25a0 Whenever you summon a creature this turn, search your deck. You may take a creature from your deck that has the same name as that creature and put it into the battle zone. Then shuffle your deck.", new[] { new PrintedRuleLine("ability.7366edaa48d6", "(This spell is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.ab05f034102f", "Whenever you summon a creature this turn, search your deck. You may take a creature from your deck that has the same name as that creature and put it into the battle zone. Then shuffle your deck.", "runtime.dm11.d2ba55909e6c") }),
                C("dm11-53-55", "Hide and Seek", new[] { Civilization.Water, Civilization.Darkness }, 4, CardType.Spell, Array.Empty<string>(), 0, "DM-11", "53/55", 838, "\u25a0 (This spell is put into your mana zone tapped.)\n\u25a0 Choose one of your opponent's non-evolution creatures in the battle zone and return it to his hand. Then he discards a card at random from his hand.", new[] { new PrintedRuleLine("ability.7366edaa48d6", "(This spell is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.5b85cda02def", "Choose one of your opponent's non-evolution creatures in the battle zone and return it to his hand. Then he discards a card at random from his hand.", "runtime.dm11.f61d691a0402") }),
                C("dm11-54-55", "Slash and Burn", new[] { Civilization.Darkness, Civilization.Fire }, 4, CardType.Spell, Array.Empty<string>(), 0, "DM-11", "54/55", 839, "\u25a0 (This spell is put into your mana zone tapped.)\n\u25a0 Whenever any of your opponent's creatures is destroyed this turn, your opponent chooses a card in his mana zone and puts it into his graveyard. Then he chooses one of his shields and puts it into his graveyard.", new[] { new PrintedRuleLine("ability.7366edaa48d6", "(This spell is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.4ee27b111df6", "Whenever any of your opponent's creatures is destroyed this turn, your opponent chooses a card in his mana zone and puts it into his graveyard. Then he chooses one of his shields and puts it into his graveyard.", "runtime.dm11.4ee27b111df6") }),
                C("dm11-55-55", "Reap and Sow", new[] { Civilization.Fire, Civilization.Nature }, 5, CardType.Spell, Array.Empty<string>(), 0, "DM-11", "55/55", 840, "\u25a0 (This spell is put into your mana zone tapped.)\n\u25a0 Choose a card in your opponent's mana zone and put it into his graveyard. Then put the top card of your deck into your mana zone.", new[] { new PrintedRuleLine("ability.7366edaa48d6", "(This spell is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.ba7875a0da69", "Choose a card in your opponent's mana zone and put it into his graveyard. Then put the top card of your deck into your mana zone.", "runtime.dm11.ba7875a0da69") }),
                C("dm12-s1-s5", "Terradragon Arque Delacerna", new[] { Civilization.Nature }, 8, CardType.Creature, new[] { "Earth Dragon" }, 6000, "DM-12", "S1/S5", 841, "\u25a0 Double breaker (This creature breaks 2 shields.)\n\u25a0 When this creature would be discarded from your hand during your opponent's turn, you may put it into the battle zone instead.", new[] { new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker"), new PrintedRuleLine("ability.bbf1ce2377fa", "When this creature would be discarded from your hand during your opponent's turn, you may put it into the battle zone instead.", "runtime.dm10.bbf1ce2377fa") }),
                C("dm12-s2-s5", "Wise Starnoid, Avatar of Hope", new[] { Civilization.Light, Civilization.Water }, 5, CardType.EvolutionCreature, new[] { "Starnoid" }, 9000, "DM-12", "S2/S5", 842, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Vortex evolution\u2014Put on one of your Light Bringers and one of your Cyber Lords.\n\u25a0 Whenever this creature attacks or leaves the battle zone, add the top card of your deck to your shields face down.\n\u25a0 Double breaker (This creature breaks 2 shields.)", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.536f11b76176", "Vortex evolution\u2014Put on one of your Light Bringers and one of your Cyber Lords.", "evolution.vortex"), new PrintedRuleLine("ability.d3321128d130", "Whenever this creature attacks or leaves the battle zone, add the top card of your deck to your shields face down.", "runtime.dm12.d3321128d130"), new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker") }),
                C("dm12-s3-s5", "Cruel Naga, Avatar of Fate", new[] { Civilization.Water, Civilization.Darkness }, 6, CardType.EvolutionCreature, new[] { "Naga" }, 9000, "DM-12", "S3/S5", 843, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Vortex evolution\u2014Put on one of your Merfolk and one of your Chimeras.\n\u25a0 This creature can't be blocked.\n\u25a0 Double breaker (This creature breaks 2 shields.)\n\u25a0 When this creature leaves the battle zone, destroy all creatures.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.48864d87eff5", "Vortex evolution\u2014Put on one of your Merfolk and one of your Chimeras.", "evolution.vortex"), new PrintedRuleLine("ability.55b08b7c26ea", "This creature can't be blocked.", "restriction.unblockable"), new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker"), new PrintedRuleLine("ability.70aebb2da07f", "When this creature leaves the battle zone, destroy all creatures.", "runtime.dm12.70aebb2da07f") }),
                C("dm12-s4-s5", "Death Phoenix, Avatar of Doom", new[] { Civilization.Darkness, Civilization.Fire }, 4, CardType.EvolutionCreature, new[] { "Phoenix" }, 9000, "DM-12", "S4/S5", 844, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Vortex evolution\u2014Put on one of your Zombie Dragons and one of your Fire Birds.\n\u25a0 Double breaker (This creature breaks 2 shields.)\n\u25a0 Whenever this creature would break a shield, your opponent puts that shield into his graveyard instead.\n\u25a0 When this creature leaves the battle zone, your opponent discards his hand.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.b5ba653a714f", "Vortex evolution\u2014Put on one of your Zombie Dragons and one of your Fire Birds.", "evolution.vortex"), new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker"), new PrintedRuleLine("ability.4a2834c8c4da", "Whenever this creature would break a shield, your opponent puts that shield into his graveyard instead.", "replacement.shield_break_to_graveyard"), new PrintedRuleLine("ability.eb10bbbcd8ce", "When this creature leaves the battle zone, your opponent discards his hand.", "runtime.dm12.eb10bbbcd8ce") }),
                C("dm12-s5-s5", "Aura Pegasus, Avatar of Life", new[] { Civilization.Light, Civilization.Nature }, 6, CardType.EvolutionCreature, new[] { "Pegasus" }, 12000, "DM-12", "S5/S5", 845, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Vortex evolution\u2014Put on one of your Horned Beasts and one of your Angel Commands.\n\u25a0 Whenever this creature attacks or leaves the battle zone, reveal the top card of your deck. If it's a non-evolution creature, put it into the battle zone. Otherwise, put it into your hand.\n\u25a0 Triple breaker (This creature breaks 3 shields.)", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.dd38716164c9", "Vortex evolution\u2014Put on one of your Horned Beasts and one of your Angel Commands.", "evolution.vortex"), new PrintedRuleLine("ability.61b53b6c8298", "Whenever this creature attacks or leaves the battle zone, reveal the top card of your deck. If it's a non-evolution creature, put it into the battle zone. Otherwise, put it into your hand.", "runtime.dm12.98ebddc21461"), new PrintedRuleLine("ability.eab4a0929dfe", "Triple breaker (This creature breaks 3 shields.)", "keyword.triple_breaker") }),
                C("dm12-1-55", "Kilstine, Nebula Elemental", new[] { Civilization.Light }, 7, CardType.Creature, new[] { "Angel Command" }, 5000, "DM-12", "1/55", 846, "\u25a0 Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)\n  Each of your creatures in the battle zone gets +5000 power and has \"blocker\" and \"double breaker\".\n", new[] { new PrintedRuleLine("ability.faa81fc27085", "Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)", "keyword.wave_striker"), new PrintedRuleLine("ability.ded454cf3c6b", "Each of your creatures in the battle zone gets +5000 power and has \"blocker\" and \"double breaker\".", "runtime.dm12.6dcf6ded2ff6") }),
                C("dm12-2-55", "Extreme Crawler", new[] { Civilization.Water }, 5, CardType.Creature, new[] { "Earth Eater" }, 7000, "DM-12", "2/55", 847, "\u25a0 When you put this creature into the battle zone, return all your other creatures from the battle zone to your hand.\n\u25a0 Double breaker (This creature breaks 2 shields.)", new[] { new PrintedRuleLine("ability.ede5ce16ff97", "When you put this creature into the battle zone, return all your other creatures from the battle zone to your hand.", "runtime.dm12.ede5ce16ff97"), new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker") }),
                C("dm12-3-55", "Necrodragon Jagraveen", new[] { Civilization.Darkness }, 6, CardType.Creature, new[] { "Zombie Dragon" }, 6000, "DM-12", "3/55", 848, "\u25a0 Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)\n\u25a0 When this creature blocks, destroy it after it battles.\n\u25a0 Double breaker (This creature breaks 2 shields.)", new[] { new PrintedRuleLine("ability.b050166a20a5", "Blocker (Whenever an opponent's creature attacks, you may tap this creature to stop the attack. Then the 2 creatures battle.)", "keyword.blocker"), new PrintedRuleLine("ability.1da00315fb36", "When this creature blocks, destroy it after it battles.", "runtime.dm12.1da00315fb36"), new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker") }),
                C("dm12-4-55", "Punch Trooper Bronks", new[] { Civilization.Fire }, 4, CardType.Creature, new[] { "Armorloid" }, 3000, "DM-12", "4/55", 849, "\u25a0 When you put this creature into the battle zone, destroy the creature that has the lowest power in the battle zone. If there's a tie, you choose from among the tied creatures.", new[] { new PrintedRuleLine("ability.bef03f146baf", "When you put this creature into the battle zone, destroy the creature that has the lowest power in the battle zone. If there's a tie, you choose from among the tied creatures.", "runtime.dm12.525b050cb153") }),
                C("dm12-5-55", "Soul Phoenix, Avatar of Unity", new[] { Civilization.Fire, Civilization.Nature }, 4, CardType.EvolutionCreature, new[] { "Phoenix" }, 13000, "DM-12", "5/55", 850, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Vortex evolution\u2014Put on one of your Fire Birds and one of your Earth Dragons.\n\u25a0 Triple breaker (This creature breaks 3 shields.)\n\u25a0 When this creature would leave the battle zone, only the top card leaves the battle zone instead. (Separate the other cards into 2 creatures.)", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.44b153fee1cc", "Vortex evolution\u2014Put on one of your Fire Birds and one of your Earth Dragons.", "evolution.vortex"), new PrintedRuleLine("ability.eab4a0929dfe", "Triple breaker (This creature breaks 3 shields.)", "keyword.triple_breaker"), new PrintedRuleLine("ability.54e9261b2fe9", "When this creature would leave the battle zone, only the top card leaves the battle zone instead. (Separate the other cards into 2 creatures.)", "runtime.dm12.7d9e31c4511b") }),
                C("dm12-6-55", "Ularus, Punishment Elemental", new[] { Civilization.Light }, 5, CardType.Creature, new[] { "Angel Command" }, 4500, "DM-12", "6/55", 851, "\u25a0 When you put this creature into the battle zone, for each creature you have in the battle zone, you may choose a shield and turn it face up. (Those shields stay face up while they're in the shield zone.)", new[] { new PrintedRuleLine("ability.6bc73b7c7ec4", "When you put this creature into the battle zone, for each creature you have in the battle zone, you may choose a shield and turn it face up. (Those shields stay face up while they're in the shield zone.)", "runtime.dm12.552c1d79bf63") }),
                C("dm12-7-55", "Cosmic Darts", new[] { Civilization.Light }, 1, CardType.Spell, Array.Empty<string>(), 0, "DM-12", "7/55", 852, "\u25a0 Your opponent chooses one of your shields. Look at it. If it's a spell, you may cast it immediately for no cost. If it's not a spell or if you don't cast it, put it back where it was.", new[] { new PrintedRuleLine("ability.c2de06789ebf", "Your opponent chooses one of your shields. Look at it. If it's a spell, you may cast it immediately for no cost. If it's not a spell or if you don't cast it, put it back where it was.", "runtime.dm12.64b3cc8047e8") }),
                C("dm12-8-55", "Typhoon Crawler", new[] { Civilization.Water }, 6, CardType.Creature, new[] { "Earth Eater" }, 5000, "DM-12", "8/55", 853, "\u25a0 This creature can't be attacked by fire or nature creatures.", new[] { new PrintedRuleLine("ability.48a5c76a2d30", "This creature can't be attacked by fire or nature creatures.", "restriction.attacked_by_two_civilizations") }),
                C("dm12-9-55", "Meloppe", new[] { Civilization.Water }, 3, CardType.Creature, new[] { "Cyber Lord" }, 1000, "DM-12", "9/55", 854, "\u25a0 Whenever your opponent would choose one of your shields, you choose instead.\n\u25a0 Whenever you would choose one of your opponent's shields, your opponent chooses instead.", new[] { new PrintedRuleLine("ability.ed496e047c67", "Whenever your opponent would choose one of your shields, you choose instead.", "runtime.dm12.ed496e047c67"), new PrintedRuleLine("ability.b060e97a7cad", "Whenever you would choose one of your opponent's shields, your opponent chooses instead.", "runtime.dm12.b060e97a7cad") }),
                C("dm12-10-55", "Gigavrand", new[] { Civilization.Darkness }, 6, CardType.Creature, new[] { "Chimera" }, 3000, "DM-12", "10/55", 855, "\u25a0 At the end of each turn, if your opponent drew 2 or more cards that turn, he discards his hand.", new[] { new PrintedRuleLine("ability.91ac5d990f78", "At the end of each turn, if your opponent drew 2 or more cards that turn, he discards his hand.", "runtime.dm12.91ac5d990f78") }),
                C("dm12-11-55", "Steamroller Mutant", new[] { Civilization.Darkness }, 4, CardType.Creature, new[] { "Hedrian" }, 3000, "DM-12", "11/55", 856, "\u25a0 Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)\n  When you put this creature into the battle zone, destroy all creatures.\n", new[] { new PrintedRuleLine("ability.faa81fc27085", "Wave striker (While 2 or more other creatures in the battle zone have \"wave striker,\" this creature has its wave striker ability.)", "keyword.wave_striker"), new PrintedRuleLine("ability.2ee5c89c30ff", "When you put this creature into the battle zone, destroy all creatures.", "destroy.selected_or_all") }),
                C("dm12-12-55", "Whirling Warrior Malian", new[] { Civilization.Fire }, 4, CardType.Creature, new[] { "Armorloid" }, 6000, "DM-12", "12/55", 857, "\u25a0 Whenever another creature is put into the battle zone, tap this creature.", new[] { new PrintedRuleLine("ability.4e95e27c563d", "Whenever another creature is put into the battle zone, tap this creature.", "runtime.dm12.4e95e27c563d") }),
                C("dm12-13-55", "Mechadragon's Breath", new[] { Civilization.Fire }, 6, CardType.Spell, Array.Empty<string>(), 0, "DM-12", "13/55", 858, "\u25a0 Choose a number less than or equal to 6000. Destroy all creatures that have that power.", new[] { new PrintedRuleLine("ability.a53f63541628", "Choose a number less than or equal to 6000. Destroy all creatures that have that power.", "runtime.dm12.a53f63541628") }),
                C("dm12-14-55", "Pincer Scarab", new[] { Civilization.Nature }, 4, CardType.Creature, new[] { "Giant Insect" }, 1000, "DM-12", "14/55", 859, "\u25a0 This creature gets +2000 power for each card in your opponent's hand.\n\u25a0 While this creature has power 6000 or more, it has \"double breaker (This creature breaks 2 shields).\"", new[] { new PrintedRuleLine("ability.ff2cbf303969", "This creature gets +2000 power for each card in your opponent's hand.", "runtime.dm12.ff2cbf303969"), new PrintedRuleLine("ability.d6a6a1225478", "While this creature has power 6000 or more, it has \"double breaker (This creature breaks 2 shields).\"", "static.power_threshold_double_breaker") }),
                C("dm12-15-55", "Radioactive Horn, the Strange", new[] { Civilization.Nature }, 3, CardType.Creature, new[] { "Horned Beast" }, 1000, "DM-12", "15/55", 860, "\u25a0 Double breaker (This creature breaks 2 shields.)", new[] { new PrintedRuleLine("ability.1bbb13e01700", "Double breaker (This creature breaks 2 shields.)", "keyword.double_breaker") }),
                C("dm12-16-55", "Agira, the Warlord Crawler", new[] { Civilization.Light, Civilization.Water }, 4, CardType.EvolutionCreature, new[] { "Gladiator", "Earth Eater" }, 5500, "DM-12", "16/55", 861, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Evolution\u2014Put on one of your Gladiators or Earth Eaters.\n\u25a0 Each of your other Gladiators and Earth Eaters in the battle zone gets +2000 power.\n\u25a0 Whenever one of your Gladiators or Earth Eaters blocks, you may draw a card.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.8bfb2f5276eb", "Evolution\u2014Put on one of your Gladiators or Earth Eaters.", "evolution.single_race"), new PrintedRuleLine("ability.85982ddd572b", "Each of your other Gladiators and Earth Eaters in the battle zone gets +2000 power.", "static.race_power_aura"), new PrintedRuleLine("ability.30f0616f85fc", "Whenever one of your Gladiators or Earth Eaters blocks, you may draw a card.", "runtime.dm12.30f0616f85fc") }),
                C("dm12-17-55", "Hydrooze, the Mutant Emperor", new[] { Civilization.Water, Civilization.Darkness }, 4, CardType.EvolutionCreature, new[] { "Cyber Lord", "Hedrian" }, 5000, "DM-12", "17/55", 862, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Evolution\u2014Put on one of your Cyber Lords or Hedrians.\n\u25a0 Each of your other Cyber Lords and Hedrians in the battle zone gets +2000 power.\n\u25a0 Your Cyber Lords and Hedrians can't be blocked.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.c8d91acbc5ba", "Evolution\u2014Put on one of your Cyber Lords or Hedrians.", "evolution.single_race"), new PrintedRuleLine("ability.59cb10a715f5", "Each of your other Cyber Lords and Hedrians in the battle zone gets +2000 power.", "static.race_power_aura"), new PrintedRuleLine("ability.8dbb642b0cae", "Your Cyber Lords and Hedrians can't be blocked.", "static.race_unblockable") }),
                C("dm12-18-55", "Phantomach, the Gigatrooper", new[] { Civilization.Darkness, Civilization.Fire }, 5, CardType.EvolutionCreature, new[] { "Chimera", "Armorloid" }, 6000, "DM-12", "18/55", 863, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Evolution\u2014Put on one of your Chimeras or Armorloids.\n\u25a0 Each of your other Chimeras and Armorloids in the battle zone gets +2000 power.\n\u25a0 Each of your Chimeras and Armorloids in the battle zone has \"double breaker.\" (A creature that has \"double breaker\" breaks 2 shields.)", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.70cecbe71764", "Evolution\u2014Put on one of your Chimeras or Armorloids.", "evolution.single_race"), new PrintedRuleLine("ability.f7d2517c0491", "Each of your other Chimeras and Armorloids in the battle zone gets +2000 power.", "static.race_power_aura"), new PrintedRuleLine("ability.b36185e71eb6", "Each of your Chimeras and Armorloids in the battle zone has \"double breaker.\" (A creature that has \"double breaker\" breaks 2 shields.)", "runtime.dm12.58e4dbf4fb2e") }),
                C("dm12-19-55", "Nemonex, Bajula's Robomantis", new[] { Civilization.Fire, Civilization.Nature }, 6, CardType.EvolutionCreature, new[] { "Xenoparts", "Giant Insect" }, 5000, "DM-12", "19/55", 864, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Evolution\u2014Put on one of your Xenoparts or Giant Insects.\n\u25a0 Each of your other XenoParts and Giant Insects in the battle zone gets +2000 power.\n\u25a0 Whenever any of your XenoParts or Giant Insects is attacking your opponent and isn't blocked, your opponent chooses a card in his mana zone and puts it into his graveyard.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.de85d855431b", "Evolution\u2014Put on one of your Xenoparts or Giant Insects.", "evolution.single_race"), new PrintedRuleLine("ability.69ae432e41f2", "Each of your other XenoParts and Giant Insects in the battle zone gets +2000 power.", "static.race_power_aura"), new PrintedRuleLine("ability.98ac5447da9c", "Whenever any of your XenoParts or Giant Insects is attacking your opponent and isn't blocked, your opponent chooses a card in his mana zone and puts it into his graveyard.", "runtime.dm12.98ac5447da9c") }),
                C("dm12-20-55", "Comet Eye, the Spectral Spud", new[] { Civilization.Light, Civilization.Nature }, 4, CardType.EvolutionCreature, new[] { "Wild Veggies", "Rainbow Phantom" }, 5500, "DM-12", "20/55", 865, "\u25a0 (This creature is put into your mana zone tapped.)\n\u25a0 Evolution\u2014Put on one of your Wild Veggies or Rainbow Phantoms.\n\u25a0 Each of your other Wild Veggies and Rainbow Phantoms in the battle zone gets +2000 power.\n\u25a0 At the end of each of your turns, you may untap any number of your Wild Veggies and Rainbow Phantoms in the battle zone.", new[] { new PrintedRuleLine("ability.ba568ea50793", "(This creature is put into your mana zone tapped.)", "rule.multicivilization_mana_tapped"), new PrintedRuleLine("ability.364bf048781a", "Evolution\u2014Put on one of your Wild Veggies or Rainbow Phantoms.", "evolution.single_race"), new PrintedRuleLine("ability.1f5e57bcda42", "Each of your other Wild Veggies and Rainbow Phantoms in the battle zone gets +2000 power.", "static.race_power_aura"), new PrintedRuleLine("ability.3b336830c0a0", "At the end of each of your turns, you may untap any number of your Wild Veggies and Rainbow Phantoms in the battle zone.", "runtime.dm12.3b336830c0a0") }),
